              steps: ['configure', 'set firewall family inet filter PROTECT-RE term OSPF from source-address 10.64.12.0/30', 'set firewall family inet filter PROTECT-RE term OSPF from protocol ospf', 'set firewall family inet filter PROTECT-RE term OSPF then accept', 'insert firewall family inet filter PROTECT-RE term OSPF before term DENY-REST', 'commit', 'run show ospf neighbor', 'exit'], needs: [0, 1, 2, 3],
